// Camada model/hooks da feature MIA — re-exports públicos
// US-025: Financeiro, Estoque, Produção, Logística
// US-026: Dashboard, NCM, NotasFiscais e demais

// Módulo Financeiro (7 abas: Executivo, Contas, Banco, Cartões, Caixa, Contabilidade, DRE)
export * from './useMiaFinanceActions';

// Módulo Estoque (5 páginas: Estoque, Movimentações, ProntaEntrega, BatchTraceability, Perdas)
export * from './useMiaStockActions';

// Módulo Produção (6 páginas: Ordens, FichasTécnicas, Insumos, PerdasQualidade, Analytics, Diária)
export * from './useMiaProductionActions';

// Módulo Logística (5 páginas: Logística, Requisição, Encomendas, ControlTower, Eventos)
export * from './useMiaLogisticsActions';

// Módulo Dashboard (filtros de setor e período)
export * from './useMiaDashboardActions';

// Módulo NCM (filtro por categoria e busca)
export * from './useMiaNcmActions';

// Módulo Produtos (catálogo: filtros, edição, ajuste de quantidade, visibilidade por loja)
export * from './useMiaProdutosActions';

// Módulo NotasFiscais (upload, filtros, modais, analytics — 11 handlers)
export * from './useMiaNotasFiscaisActions';

// Dispatcher central de ações da MIA
// Os hooks de domínio são importados pelas páginas via @/features/mia/model/hooks
// e registram seus handlers diretamente no contexto MIA via useMiaActions (src/hooks/useMiaActions).
//
// Fluxo de dispatch em runtime:
//   página → hook de domínio (ex: useMiaBankActions) → useMiaActions('/rota', handlers)
//   → MiaContext.registerActions → agente MIA executa o handler correto
//
// Este dispatcher é um ponto de entrada programático alternativo
// para casos onde a ação precisa ser disparada fora de um componente React.

// Tipos do dispatcher
export interface MiaActionDispatchParams {
  actionType: string;
  params: Record<string, any>;
  route?: string;
}

export interface MiaActionDispatchResult {
  success: boolean;
  error?: string;
}

/**
 * Hook dispatcher central da MIA (US-025/026 — hooks de domínio integrados).
 *
 * Os hooks de domínio disponíveis (importáveis de @/features/mia/model/hooks):
 * - Financeiro: useMiaFinanceiroActions, useMiaBankActions, useMiaCartoesActions, useMiaCaixaActions, useMiaAccountingActions
 * - Estoque: useMiaEstoqueActions, useMiaMovimentacoesActions, useMiaProntaEntregaActions, useMiaBatchTraceabilityActions, useMiaPerdasActions
 * - Produção: useMiaProducaoActions, useMiaFichasTecnicasActions, useMiaInsumosActions, useMiaPerdasQualidadeActions, useMiaProducaoAnalyticsActions, useMiaProducaoDiariaActions
 * - Logística: useMiaLogisticaActions, useMiaRequisicaoActions, useMiaEncomendasActions, useMiaControlTowerActions, useMiaEventosActions
 * - Dashboard: useMiaDashboardActions
 * - NCM: useMiaNCMActions
 * - Produtos: useMiaProdutosActions
 * - NotasFiscais: useMiaNotasFiscaisActions (11 handlers: filter, search, status, date_range, analytics, upload, details, edit, reports, sort, clear)
 */
export function useMiaActionsDispatcher() {
  const dispatch = async (dispatchParams: MiaActionDispatchParams): Promise<MiaActionDispatchResult> => {
    // O dispatch programático não é necessário no fluxo normal:
    // cada hook de domínio registra seus handlers via useMiaActions('/rota', handlers)
    // e o agente MIA os invoca diretamente pelo contexto.
    //
    // Este stub é mantido para casos de uso futuro (ex: orquestração cross-domain).
    console.error(
      `[MiaActionsDispatcher] Dispatch programático não implementado para "${dispatchParams.actionType}". ` +
      'Use os hooks de domínio via @/features/mia/model/hooks para registrar handlers no contexto MIA.'
    );
    return { success: false, error: 'Use os hooks de domínio via model/hooks para registro de handlers MIA' };
  };

  return { dispatch };
}

