import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';
import { useAuth } from '@/hooks/useAuth';
import { precoPorUnidadeProducao } from './custoModel';

export type CategoriaInsumo =
  | 'farinha'
  | 'laticinio'
  | 'ovo'
  | 'chocolate'
  | 'acucar'
  | 'gordura'
  | 'fruta'
  | 'noz'
  | 'embalagem'
  | 'bebida'
  | 'condimento'
  | 'outros';

export const CATEGORIAS_INSUMO: { value: CategoriaInsumo; label: string }[] = [
  { value: 'farinha', label: 'Farinha e Amidos' },
  { value: 'laticinio', label: 'Laticínios' },
  { value: 'ovo', label: 'Ovos' },
  { value: 'chocolate', label: 'Chocolate e Cacau' },
  { value: 'acucar', label: 'Açúcar e Mel' },
  { value: 'gordura', label: 'Gorduras e Óleos' },
  { value: 'fruta', label: 'Frutas e Polpas' },
  { value: 'noz', label: 'Nozes e Sementes' },
  { value: 'bebida', label: 'Bebidas e Licores' },
  { value: 'condimento', label: 'Condimentos e Especiarias' },
  { value: 'embalagem', label: 'Embalagens' },
  { value: 'outros', label: 'Outros' },
];

export const ALERGENOS_OPCOES = [
  'glúten',
  'laticínio',
  'ovo',
  'amendoim',
  'nozes',
  'soja',
  'peixe',
  'frutos do mar',
  'gergelim',
  'sulﬁtos',
];

export const UNIDADES_COMPRA = [
  { value: 'kg', label: 'kg' },
  { value: 'g', label: 'g' },
  { value: 'L', label: 'L' },
  { value: 'mL', label: 'mL' },
  { value: 'un', label: 'unidade' },
  { value: 'cx', label: 'caixa' },
  { value: 'fardo', label: 'fardo' },
  { value: 'saco', label: 'saco' },
];

export const UNIDADES_PRODUCAO = [
  { value: 'g', label: 'g' },
  { value: 'kg', label: 'kg' },
  { value: 'mL', label: 'mL' },
  { value: 'L', label: 'L' },
  { value: 'un', label: 'unidade' },
];

export interface Insumo {
  id: number;
  nome: string;
  codigo_interno: string | null;
  categoria: CategoriaInsumo;
  unidade_compra: string;
  unidade_producao: string;
  fator_conversao: number;
  fator_correcao: number;
  preco_custo: number;
  preco_custo_producao: number;
  estoque_minimo: number | null;
  fornecedor_principal: string | null;
  alergenos: string[];
  dias_validade: number | null;
  observacoes: string | null;
  ativo: boolean;
  produto_master_id: number | null; // <-- NEW
  produto_master_nome?: string; // <-- NEW
  created_at: string;
  updated_at: string;
}

export interface InsumoForm {
  nome: string;
  codigo_interno: string;
  categoria: CategoriaInsumo;
  unidade_compra: string;
  unidade_producao: string;
  fator_conversao: number;
  fator_correcao: number;
  preco_custo: number;
  estoque_minimo: number | null;
  fornecedor_principal: string;
  alergenos: string[];
  dias_validade: number | null;
  observacoes: string;
  ativo: boolean;
  produto_master_id: number | null; // <-- NEW
}

const toInsumo = (row: Record<string, unknown>): Insumo => ({
  id: row.id as number,
  nome: row.nome as string,
  codigo_interno: row.codigo_interno as string | null,
  categoria: row.categoria as CategoriaInsumo,
  unidade_compra: row.unidade_compra as string,
  unidade_producao: row.unidade_producao as string,
  fator_conversao: Number(row.fator_conversao),
  fator_correcao: Number(row.fator_correcao),
  preco_custo: Number(row.preco_custo),
  // Preço por unidade de produção = preço de compra convertido (espelha o banco).
  // Pares padrão (g↔kg, mL↔L) usam conversão física; não-padrão usam fator_conversao.
  preco_custo_producao: precoPorUnidadeProducao({
    preco_custo: Number(row.preco_custo),
    unidade_producao: row.unidade_producao as string | null,
    unidade_compra: row.unidade_compra as string | null,
    fator_conversao: Number(row.fator_conversao),
  }),
  estoque_minimo: row.estoque_minimo != null ? Number(row.estoque_minimo) : null,
  fornecedor_principal: row.fornecedor_principal as string | null,
  alergenos: (row.alergenos as string[]) ?? [],
  dias_validade: row.dias_validade != null ? Number(row.dias_validade) : null,
  observacoes: row.observacoes as string | null,
  ativo: row.ativo as boolean,
  produto_master_id: row.produto_master_id as number | null,
  produto_master_nome: (row as Record<string, unknown> & { produtos_master?: { nome?: string } }).produtos_master?.nome,
  created_at: row.created_at as string,
  updated_at: row.updated_at as string,
});

export const useInsumos = () => {
  const { user } = useAuth();
  const [insumos, setInsumos] = useState<Insumo[]>([]);
  const [loading, setLoading] = useState(true);

  const fetch = useCallback(async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('insumos')
        .select('*, produtos_master(nome)')
        .order('nome');
      if (error) throw error;
      setInsumos((data ?? []).map((r) => toInsumo(r as Record<string, unknown>)));
    } catch (e) {
      console.error(e);
      toast.error('Erro ao carregar insumos');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetch();
  }, [fetch]);

  const criar = async (form: InsumoForm): Promise<boolean> => {
    try {
      const { error } = await supabase.from('insumos').insert({
        ...form,
        created_by: user?.id,
      });
      if (error) throw error;
      toast.success(`Insumo "${form.nome}" criado com sucesso`);
      await fetch();
      return true;
    } catch (e) {
      console.error(e);
      toast.error('Erro ao criar insumo');
      return false;
    }
  };

  const atualizar = async (id: number, form: Partial<InsumoForm>): Promise<boolean> => {
    try {
      const { error } = await supabase.from('insumos').update(form).eq('id', id);
      if (error) throw error;
      toast.success('Insumo atualizado');
      await fetch();
      return true;
    } catch (e) {
      console.error(e);
      toast.error('Erro ao atualizar insumo');
      return false;
    }
  };

  const remover = async (id: number): Promise<boolean> => {
    try {
      const { error } = await supabase.from('insumos').delete().eq('id', id);
      if (error) throw error;
      toast.success('Insumo removido');
      setInsumos((prev) => prev.filter((i) => i.id !== id));
      return true;
    } catch (e) {
      console.error(e);
      toast.error('Erro ao remover insumo');
      return false;
    }
  };

  const toggleAtivo = async (id: number, ativo: boolean): Promise<void> => {
    await atualizar(id, { ativo });
  };

  return { insumos, loading, fetch, criar, atualizar, remover, toggleAtivo };
};
